#!/usr/bin/env python3
# Writes aces.frag: a synthetic stand-in for the shape of UE4's colour-grading LUT shader
# (CombineLUTs) that the Mali-G925's compiler never finished (docs: w3-stall-report).
DEPTH = 44
w = []
w.append("""#version 450
// Generated by gen_aces.py: the shape of UE4's colour-grading LUT fragment shader (CombineLUTs) that
// the Mali-G925's compiler never finished (Stray, 2026-10-14) - segmented ACES-style splines over a
// dynamically indexed 16-entry constant buffer, exp2/log2/fma chains, 44 nested ifs with values
// flowing out of every level. Not the game's shader; a compile-time probe of the same constructs.
layout(location = 0) noperspective in vec2 uv;
layout(location = 0) out vec4 o;
layout(set = 0, binding = 0) uniform U { vec4 c[16]; vec4 k; } u;
float spline(float x, int base) {
    float lx = log2(max(x, 1e-10)) * 0.30103;
    float t = clamp((lx + 2.5) * 1.4, 0.0, 6.999);
    int j = int(t);
    float f = fract(t);
    vec3 m = vec3(u.c[(base + j) & 15].x, u.c[(base + j + 1) & 15].y, u.c[(base + j + 2) & 15].z);
    vec3 cf = vec3(dot(m, vec3(0.5, -1.0, 0.5)), dot(m, vec3(-1.0, 1.0, 0.0)), dot(m, vec3(0.5, 0.5, 0.0)));
    return exp2(fma(fma(cf.x, f, cf.y), f, cf.z) * 3.321928);
}
vec3 rrt(vec3 c, int base) {
    float sat = (max(c.r, max(c.g, c.b)) - min(c.r, min(c.g, c.b))) / max(max(c.r, max(c.g, c.b)), 1e-4);
    float hue = atan(1.7320508 * (c.g - c.b), 2.0 * c.r - c.g - c.b);
    float glow = 1.0 + 0.05 * sat * exp2(-hue * hue);
    c *= glow;
    return vec3(spline(c.r, base), spline(c.g, base + 3), spline(c.b, base + 7));
}
void main() {
    vec3 n = vec3(uv, u.k.w);
    vec3 c = max(exp2((n - 0.434017599) * 14.0) * 0.18 - 0.00266771927, 0.0);
    float acc = 0.0;""")
for i in range(DEPTH):
    ind = "    " * (i + 1)
    w.append(f"{ind}if (c.r * u.c[{i % 16}].w + c.g > u.c[(int(acc * 7.0) + {i}) & 15].x) {{")
    w.append(f"{ind}    c = rrt(c, {i % 16});")
    w.append(f"{ind}    acc = fma(acc, u.k.x, log2(c.g + 1.0)) + exp2(-c.b);")
for i in reversed(range(DEPTH)):
    ind = "    " * (i + 1)
    w.append(f"{ind}}} else {{")
    w.append(f"{ind}    c = c.gbr * u.c[{(i * 5) % 16}].xyz + vec3(acc);")
    w.append(f"{ind}    acc = fma(acc, u.k.y, c.r);")
    w.append(f"{ind}}}")
w.append("    o = vec4(clamp(c / 1.05, 0.0, 1.0), acc);\n}")
open("aces.frag", "w").write("\n".join(w) + "\n")
